import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

const Header = () => {
  const navigate = useNavigate();
  const [showDropdown, setShowDropdown] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const email = localStorage.getItem("email") || "Unknown";
  const role = localStorage.getItem("role");

  return (
    <header className="modern-header">
      <div className="header-bar" />
      <div className="header-container">
        <div className="logo" onClick={() => navigate('/home')}>
          <span style={{ marginRight: 8, fontSize: 28, verticalAlign: 'middle' }}>🛒</span>
          <span style={{ letterSpacing: 2 }}>INVENTORY</span>
        </div>
        <nav className={`nav-links${mobileNav ? ' nav-mobile-open' : ''}`}>
          {role === "admin" && <Link to="/home">HOME</Link>}
          <Link to="/products">PRODUCTS</Link>
          <Link to="/category">CATEGORIES</Link>
          <Link to="/brand">BRANDS</Link>
          <button
            className="logout-btn nav-mobile-btn"
            onClick={() => {
              localStorage.removeItem("token");
              localStorage.removeItem("role");
              localStorage.removeItem("name");
              localStorage.removeItem("email");
              navigate("/login");
            }}
          >
            Logout
          </button>
        </nav>
        <div className="header-actions">
          <div className="profile-container" onClick={() => setShowDropdown(!showDropdown)}>
            {/* Replace image with a user icon */}
            <span className="profile-icon" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 22, background: 'var(--color-surface)', color: 'var(--color-primary)', width: 32, height: 32, borderRadius: '50%' }}>
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <circle cx="12" cy="8.5" r="4.5" stroke="currentColor" strokeWidth="2"/>
                <path d="M4 20c0-2.761 3.582-5 8-5s8 2.239 8 5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
              </svg>
            </span>
            {showDropdown && (
              <div className="profile-dropdown">
                <p style={{ margin: 0, fontSize: 13 }}>Logged in as:</p>
                <strong style={{ fontSize: 14 }}>{email}</strong>
              </div>
            )}
          </div>
          <button
            className="logout-btn desktop-only"
            onClick={() => {
              localStorage.removeItem("token");
              localStorage.removeItem("role");
              localStorage.removeItem("name");
              localStorage.removeItem("email");
              navigate("/login");
            }}
          >
            Logout
          </button>
          <button
            className="hamburger"
            aria-label="Open navigation"
            onClick={() => setMobileNav((v) => !v)}
          >
            <span className="hamburger-bar" />
            <span className="hamburger-bar" />
            <span className="hamburger-bar" />
          </button>
        </div>
      </div>
    </header>
  );
};

export default Header;
